#!/usr/bin/env python3
"""Render measured captions and all scores as one self-contained listening page."""
import argparse
import base64
import hashlib
import html
import json
from pathlib import Path


PAGE = r'''<!doctype html><html lang="en"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Humaneness Ears Medium · Procedural Voice Captions</title>
<style>
:root{color-scheme:dark;--bg:#101522;--panel:#192235;--line:#334059;--text:#edf3ff;--muted:#b2c0d8;--cyan:#79dfdc;--violet:#b4a0ff;--rose:#f8a5b8}*{box-sizing:border-box}
body{margin:0;background:var(--bg);color:var(--text);font:16px/1.65 system-ui,sans-serif}a{color:var(--cyan)}main{max-width:1350px;margin:auto;padding:30px 24px 80px}h1{font-size:clamp(32px,5vw,64px);line-height:1.1;max-width:1000px;margin:20px 0}h2{font-size:23px;line-height:1.25}h3{font-size:17px}p{max-width:1000px}.eyebrow{color:var(--cyan);letter-spacing:.15em;text-transform:uppercase;font-size:12px}.muted{color:var(--muted);font-size:14px}.intro,.card{background:var(--panel);border:1px solid var(--line);border-radius:18px;padding:24px;margin:18px 0}.intro{background:linear-gradient(120deg,#203450,#24253e)}.pills,.toolbar{display:flex;gap:10px;flex-wrap:wrap}.pill{padding:5px 12px;border:1px solid var(--line);border-radius:30px;font-size:13px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}.card{margin:0;min-width:0;scroll-margin-top:20px}.wide{grid-column:1/-1}.caption{border-left:3px solid var(--cyan);background:#121b2c;padding:15px;white-space:pre-wrap;overflow-wrap:anywhere}.cue{color:var(--violet);font-weight:600}.script{max-height:330px;overflow:auto}audio{width:100%;margin:12px 0}button,select,input{color:var(--text);background:#122035;border:1px solid var(--line);border-radius:8px;padding:8px;font:inherit}button{cursor:pointer}details{border-top:1px solid var(--line);margin-top:14px;padding-top:12px}summary{cursor:pointer;font-weight:650}.table-wrap{overflow:auto;max-height:550px}table{border-collapse:collapse;width:100%;font-size:13px}td,th{padding:9px 7px;border-bottom:1px solid var(--line);text-align:left}th{color:var(--muted);position:sticky;top:0;background:var(--panel)}td.num{font-variant-numeric:tabular-nums;text-align:right}.bar{width:110px;min-width:110px;height:10px;background:#101522;position:relative}.bar:after{content:'';position:absolute;left:50%;height:100%;border-left:1px solid #7a899f}.fill{position:absolute;height:100%;background:var(--cyan)}.fill.neg{background:var(--rose)}svg.timeline{width:100%;height:86px;background:#0e192c;border-radius:8px}.event{font-size:13px;padding:8px 0;border-bottom:1px solid var(--line)}.seek{font-variant-numeric:tabular-nums;font-size:12px;color:var(--cyan)}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:13px}code{font-size:13px;color:var(--cyan)}.path{overflow-wrap:anywhere}.hidden{display:none!important}.smallplot{height:30px;width:100%}.empty{color:var(--muted);font-style:italic}footer{margin-top:30px;color:var(--muted)}@media(max-width:850px){.grid{grid-template-columns:1fr}main{padding:20px 14px}.intro,.card{padding:18px}}
</style></head><body><main>
<div class="eyebrow">LAION · Open listening models · Reproducible procedural captions</div>
<h1>Hear the voice.<br>Read what the model hears.</h1>
<p>Forty real, playable examples scored by <strong>Humaneness Ears Medium</strong>: twenty generated acting performances in German and English, and twenty recordings from the multilingual Emilia collection. The voice descriptions are generated by transparent rules from model predictions. No language model writes these captions.</p>
<div class="pills"><a class="pill" href="../">All procedural-caption demos</a><a class="pill" href="https://github.com/LAION-AI/procedural-voice-captions">Code and measured normalization</a><a class="pill" href="https://huggingface.co/laion/humaneness-ears-base-medium">Pinned model family</a><a class="pill" href="#methods">How to interpret the results</a></div>
<section class="intro" id="methods"><h2>One encoder, many listening tasks</h2>
<p>Medium uses a fine-tuned <strong>Whisper Small encoder</strong> with multiple prediction heads. It is an encoder-only annotation model, with approximately 97.1 million parameters. It does not transcribe audio. <a href="https://huggingface.co/nvidia/parakeet-tdt-0.6b-v3">Parakeet v3</a> separately supplies transcription and word timestamps, using the existing alignment and RMS word-end trimming in this repository.</p>
<table><thead><tr><th>Prediction</th><th>What is shown</th><th>How to read it</th></tr></thead><tbody>
<tr><td>40 emotion and 57 VoiceNet dimensions</td><td>Raw regression scores, reference z-scores, and rule-based descriptions</td><td>Scores describe model-estimated vocal delivery, not a person's psychological state.</td></tr>
<tr><td>AudioBox Content Enjoyment</td><td>Raw score and z-score; the source of enjoyable / less-enjoyable wording</td><td>VoiceNet ESTH is preserved as a raw prediction but cannot supply pleasantness wording.</td></tr>
<tr><td>Vocal-burst intervals</td><td>Start and end time, onset confidence, event-local top three of 53 class labels</td><td>These are predictions, not human-verified event boundaries. Class softmax values are not calibrated confidence estimates.</td></tr>
<tr><td>All 192 targets + CPS and burst count</td><td>Expandable tables with raw value and measured reference z-score</td><td>Includes additional EIV, AudioBox, DNSMOS, genuineness, blend and VoiceCLAP attribute targets.</td></tr>
<tr><td>Orange embeddings</td><td>128-dimensional timbre and 250-dimensional identity vectors in each downloadable annotation</td><td>Predicted embeddings; the original Orange teacher is not run here.</td></tr>
</tbody></table>
<h3>A measured reference, not an inherited teacher baseline</h3><p>__REFERENCE_SUMMARY__ Each successfully annotated clip has equal weight. The normalization is <code>z = (raw prediction − arithmetic mean) / population standard deviation</code>, calculated in float64 from stored float32 Medium predictions. <strong>z = +2</strong> means two standard deviations above this particular reference; it is not a probability. Bars show z, clipped only for display at ±3. All raw values remain available.</p>
<p>Caption selection uses the largest absolute z-score within the emotion and VoiceNet pools. Consequently, a caption can describe both a strong property and a conspicuously weak one. The existing genuineness wording gate is retained, using the new mean as its center. The old teacher's per-dimension reliability coefficients are not reused for this student model. Age, perceived vocal gender and register retain the existing ordinal wording rules; they are voice attributes, not verified demographic facts.</p>
<p>Recordings longer than 30 seconds use overlapping windows. Global scores are averaged with weights that partition the original duration; event proposals are assigned by their midpoint and converted to full-recording timestamps. Frame probabilities are blended across overlap regions. Low-confidence event names are written as “Vocal Burst”; their actual top-three predictions remain visible.</p>
<p><strong>Language coverage:</strong> Parakeet supports the German, English and French examples. It is explicitly skipped for Japanese, Korean and Chinese. For those examples, existing corpus text is displayed separately with no invented word timestamps. Medium still predicts all acoustic scores and vocal-burst intervals.</p>
<p class="muted path">Model revision: <code>818506970d93c809a3295a0a02c40dee8ff2bfc3</code> · Reference SHA-256: <code>__REFERENCE_HASH__</code> · Normalization SHA-256: <code>__BASELINE_HASH__</code>. The reference is for caption normalization, not a held-out benchmark. Existing audio and teacher annotations are preserved; new values use the <code>humaneness_ears_medium</code> namespace.</p>
<p class="muted">New code, captions and reference statistics: CC BY 4.0. Source audio retains its original terms; the Emilia release distinguishes CC BY-NC 4.0 Emilia from CC BY 4.0 Emilia-YODAS. Source attribution is included per card. This mixed listening selection does not grant a blanket audio license.</p>
</section>
<h2 id="listen">Start listening</h2><p>Each audio is embedded as a mono 128-kbit/s MP3, so this page also works after downloading. Click an interval to seek to that event. Expand the score tables to inspect every predicted target.</p>
<div class="toolbar"><label>Source <select id="source-filter"><option value="">All</option><option value="gemini_acting">Gemini acting</option><option value="emilia_multilingual">Emilia</option></select></label><label>Language <select id="language-filter"><option value="">All</option><option>de</option><option>en</option><option>fr</option><option>ja</option><option>ko</option><option>zh</option></select></label><label>Find a clip <input id="search" placeholder="Title or sample ID"></label><span id="visible" class="muted"></span></div>
<div class="grid">__CARDS__</div>
<footer>Generated from saved model predictions. Audio and original annotations are unchanged in the source archives. Source collections: <a href="https://huggingface.co/datasets/laion/tts-scaling-ladder-de-en">S10 scaling ladder</a>, <a href="https://github.com/LAION-AI/Voice-Acting-Pipeline">Voice-Acting-Pipeline</a>, and <a href="https://huggingface.co/datasets/amphion/Emilia-Dataset">Emilia</a>. <a href="https://github.com/LAION-AI/procedural-voice-captions/blob/main/HUMANENESS_MEDIUM.md">Methods and reproduction</a>.</footer>
<script id="annotation-data" type="application/json">__ANNOTATIONS__</script>
<script>
const annotations=JSON.parse(document.getElementById('annotation-data').textContent);
document.querySelectorAll('[data-seek]').forEach(button=>button.addEventListener('click',()=>{const player=button.closest('.card').querySelector('audio');player.currentTime=Number(button.dataset.seek);player.play()}));
document.querySelectorAll('[data-download]').forEach(button=>button.addEventListener('click',()=>{const index=Number(button.dataset.download);const blob=new Blob([JSON.stringify(annotations[index],null,2)],{type:'application/json'});const u=URL.createObjectURL(blob);const a=document.createElement('a');a.href=u;a.download='humaneness-medium-'+String(index+1).padStart(2,'0')+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}));
function filterCards(){const source=document.getElementById('source-filter').value,language=document.getElementById('language-filter').value,q=document.getElementById('search').value.toLowerCase();let n=0;document.querySelectorAll('.card').forEach(card=>{const show=(!source||card.dataset.source===source)&&(!language||card.dataset.language===language)&&(!q||card.dataset.search.includes(q));card.classList.toggle('hidden',!show);n+=show});document.getElementById('visible').textContent=n+' / 40 clips'}
['source-filter','language-filter','search'].forEach(id=>document.getElementById(id).addEventListener('input',filterCards));filterCards();
document.querySelectorAll('.score-search').forEach(input=>input.addEventListener('input',()=>{const q=input.value.toLowerCase();input.closest('details').querySelectorAll('tbody tr').forEach(row=>row.classList.toggle('hidden',!row.dataset.name.includes(q)))}));
</script></main></body></html>'''


def escape(value):
    return html.escape(str(value), quote=True)


def pretty(name):
    if name.startswith("emo_"):
        return name[4:].replace("_", " ")
    if name.startswith("vn_"):
        return "VoiceNet " + name[3:].removesuffix("_reg")
    return name.replace("_", " ")


def table(values, stats, predicate=lambda name: True):
    rows = []
    for name, raw in values.items():
        if not predicate(name):
            continue
        st = stats[name]
        z = (raw-st["mean"])/st["std"] if st["z_defined"] else None
        width = min(3, abs(z or 0))/6*100
        left = 50 if (z or 0) >= 0 else 50-width
        bar = f'<div class="bar"><span class="fill {"neg" if (z or 0)<0 else ""}" style="left:{left:.2f}%;width:{width:.2f}%"></span></div>'
        rows.append((abs(z or 0), f'<tr data-name="{escape(pretty(name).lower())}"><td>{escape(pretty(name))}<br><span class="muted">{escape(name)}</span></td><td class="num">{raw:.3f}</td><td class="num">{z:+.2f}</td><td>{bar}</td></tr>' if z is not None else f'<tr data-name="{escape(pretty(name).lower())}"><td>{escape(pretty(name))}</td><td>{raw:.3f}</td><td>undefined (zero variance)</td><td></td></tr>'))
    rows.sort(key=lambda item: item[0], reverse=True)
    return '<input class="score-search" placeholder="Filter targets" aria-label="Filter score rows"><div class="table-wrap"><table><thead><tr><th>Target</th><th>Raw</th><th>z</th><th>−3 · 0 · +3</th></tr></thead><tbody>' + ''.join(row for _, row in rows) + '</tbody></table></div>'


def card(index, result, audio, baseline):
    source = result["source"]
    prediction = result["humaneness_ears_medium"]
    raw = dict(prediction["scores_raw"])
    raw.update({key: prediction[key] for key in ["characters_per_second", "estimated_burst_count"]})
    duration = result["dur"]
    events = prediction["burst_event_proposals"]
    rects, event_text = [], []
    for i, event in enumerate(events):
        start, end = event["start_s"], event["end_s"]
        x, width = start/duration*1000, max(1, (end-start)/duration*1000)
        rects.append(f'<rect x="{x:.2f}" y="{12+(i%3)*13}" width="{width:.2f}" height="10" rx="2" fill="#b4a0ff"><title>{escape(start)}–{escape(end)} seconds</title></rect>')
        labels = '; '.join(f'{escape(t["label"])} {t["softmax_probability"]:.1%}' for t in event["top3_classes"])
        event_text.append(f'<div class="event"><button class="seek" data-seek="{start:.4f}">{start:.2f}–{end:.2f} s</button> · onset {event["onset_probability"]:.1%}<br>{labels}</div>')
    frame = prediction.get("burst_probability_per_20ms_frame", [])
    # Downsample only the drawing; the full 20-ms probabilities remain in JSON.
    stride = max(1, len(frame)//500)
    points = ' '.join(f'{i/max(1,len(frame)-1)*1000:.2f},{75-float(frame[i])*22:.2f}' for i in range(0,len(frame),stride))
    timeline = '<svg class="timeline" viewBox="0 0 1000 86" role="img" aria-label="Predicted burst intervals and frame probability">'+''.join(rects)+f'<polyline points="{points}" fill="none" stroke="#79dfdc" stroke-width="1.5"/><text x="4" y="84" fill="#b2c0d8" font-size="11">0 s</text><text x="940" y="84" fill="#b2c0d8" font-size="11">{duration:.1f} s</text></svg>'
    scripts = ''.join(f'<p><span class="cue">{escape(sentence.get("caption", ""))}</span><br>{escape(sentence.get("text", ""))}</p>' for sentence in result.get("sentences", []))
    if not scripts:
        scripts = '<p class="empty">No Parakeet transcript or word alignment for this language.</p>'
    original = ''
    if result.get("source_transcript"):
        original = '<details><summary>Existing corpus transcript (not model-generated)</summary><p>'+escape(result["source_transcript"])+ '</p><p class="muted">No timestamp alignment is inferred from this text.</p></details>'
    title = source.get("title") or source["source_key"]
    blob = base64.b64encode(audio).decode('ascii')
    groups = [
        ("40 emotion dimensions · raw and z", lambda n: n.startswith("emo_")),
        ("57 VoiceNet dimensions · raw and z", lambda n: n.startswith("vn_")),
        ("Quality, enjoyment, CPS, genuineness and all remaining targets", lambda n: not n.startswith(("emo_", "vn_"))),
    ]
    tables = ''.join('<details><summary>'+label+'</summary>'+table(raw,baseline["_raw_targets"],predicate)+'</details>' for label,predicate in groups)
    event_section = ''.join(event_text) if event_text else '<p class="empty">No event proposals above the onset threshold. This does not prove the absence of vocal bursts.</p>'
    lines = result.get("script_timed") or [f'({line["cue"]}) {line["text"]}' for line in result.get("script_lines", [])] or [result.get("variant_a_inline", "")]
    script_timed = '<details><summary>Timed procedural script, pauses and inline events</summary><pre>'+escape('\n'.join(lines))+'</pre></details>'
    return f'''<article class="card" id="sample-{index+1:02d}" data-source="{escape(source['source'])}" data-language="{escape(source['language'])}" data-search="{escape((title+' '+source['id']).lower())}">
    <div class="eyebrow">{escape(source['source'])} · {escape(source['language'].upper())} · {duration:.1f} s</div><h2>{escape(title)}</h2>
    <p class="muted path">{escape(source['id'])}{' · voice '+escape(source['voice']) if source.get('voice') else ''}</p>
    <audio controls preload="none" src="data:audio/mpeg;base64,{blob}"></audio>
    <h3>General voice description</h3><div class="caption">{escape(result['global_caption'])}</div>
    <h3>Predicted burst intervals · {len(events)} proposals</h3>{timeline}<div>{event_section}</div>
    <details open><summary>Sentence delivery and Parakeet transcript</summary><p class="muted">{escape(result['asr']['status'])} · {len(result['words'])} timestamped words</p><div class="script">{scripts}</div></details>
    {script_timed}{original}{tables}<details><summary>Predicted Orange embeddings and complete annotation</summary><p>Timbre: 128 dimensions. Identity: 250 dimensions. The JSON also contains raw and training-normalized scores, every 20-ms burst probability, interval predictions and per-sentence scores.</p><button data-download="{index}">Download annotation JSON</button><p class="muted">MP3 SHA-256: <span class="path">{escape(result['audio_mp3_sha256'])}</span></p></details>
    <p class="muted">Source: {escape(source['source_dataset'])}. ASR text and acoustic predictions are machine-generated and may contain errors.</p></article>'''


def render(args):
    baseline = json.loads(args.baseline.read_text())
    files = sorted(args.demo.glob("demo-*.json"))
    if len(files) != 40:
        raise RuntimeError(f"Expected 40 completed predictions, found {len(files)}")
    data = [json.loads(path.read_text()) for path in files]
    baseline_hash = hashlib.sha256(args.baseline.read_bytes()).hexdigest()
    if any(row["normalization_sha256"] != baseline_hash for row in data):
        raise ValueError("Mixed demo normalizations")
    for row in data:
        raw = row["humaneness_ears_medium"]["scores_raw"]
        row["humaneness_ears_medium"]["scores_reference_z"] = {
            name: (value-baseline["_raw_targets"][name]["mean"])/baseline["_raw_targets"][name]["std"]
            if baseline["_raw_targets"][name]["z_defined"] else None for name,value in raw.items()}
        row["humaneness_ears_medium"]["auxiliary_reference_z"] = {
            name: (row["humaneness_ears_medium"][name]-baseline["_raw_targets"][name]["mean"])/baseline["_raw_targets"][name]["std"]
            if baseline["_raw_targets"][name]["z_defined"] else None for name in ["characters_per_second", "estimated_burst_count"]}
    cards = ''.join(card(i, row, files[i].with_suffix('.mp3').read_bytes(),baseline) for i,row in enumerate(data))
    counts = baseline["_provenance"]["source_counts"]
    summary = 'The reference contains ' + f'{baseline["_provenance"]["n"]:,} clips: ' + ', '.join(f'{count:,} {name.replace("_", " ")}' for name,count in counts.items()) + '.'
    page = PAGE.replace('__REFERENCE_SUMMARY__',summary).replace('__REFERENCE_HASH__',baseline['_provenance']['source_manifest']['manifest_sha256']).replace('__BASELINE_HASH__',baseline_hash).replace('__CARDS__',cards).replace('__ANNOTATIONS__',json.dumps(data,ensure_ascii=False,separators=(',',':'),allow_nan=False).replace('</',r'<\/'))
    args.output.parent.mkdir(parents=True,exist_ok=True)
    args.output.write_text(page)
    args.output.with_name('annotations.jsonl').write_text(''.join(json.dumps(row,ensure_ascii=False,separators=(',',':'),allow_nan=False)+'\n' for row in data))
    # Basic publication gate: real embedded audio, complete raw output, real interval pairs.
    assert page.count('data:audio/mpeg;base64,') == 40
    assert all(len(row['humaneness_ears_medium']['scores_raw']) == 192 for row in data)
    assert all(0 <= event['start_s'] < event['end_s'] <= row['dur'] for row in data for event in row['humaneness_ears_medium']['burst_event_proposals'])
    print('LISTENING PAGE READY',args.output,'bytes',args.output.stat().st_size,flush=True)


if __name__ == '__main__':
    p=argparse.ArgumentParser(description=__doc__)
    for name in ['demo','baseline','output']:p.add_argument('--'+name,type=Path,required=True)
    render(p.parse_args())
